const asterisRaw = $('Scrape Asteris.com').first().json;
const stableRaw = $('Scrape StableTrack.ai').first().json;

const asterisContent = (asterisRaw.data || asterisRaw.body || JSON.stringify(asterisRaw) || '').substring(0, 4000);
const stableContent = (stableRaw.data || stableRaw.body || JSON.stringify(stableRaw) || '').substring(0, 4000);

// Determine content type by day of week
const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const today = days[new Date().getDay()];

let contentType = 'Industry Insight';
let product = 'Both';

if (today === 'Mon') { contentType = 'Pain Point Post'; product = 'StableTrack'; }
if (today === 'Tue') { contentType = 'Feature Spotlight'; product = 'New Lumen'; }
if (today === 'Wed') { contentType = 'Case Study Snippet'; product = 'StableTrack'; }
if (today === 'Thu') { contentType = 'AI Demo Pitch'; product = 'New Lumen'; }
if (today === 'Fri') { contentType = 'Industry Insight'; product = 'Both'; }
if (today === 'Sat' || today === 'Sun') { contentType = 'Weekend Thought'; product = 'Both'; }

return [{
  json: {
    asterisContent,
    stableContent,
    contentType,
    product,
    today
  }
}];

const prep = $('Prep Product Data').first().json;

const vetRaw = $('DDG Vet Discussions').first().json;
const vetData = (vetRaw.data || vetRaw.body || JSON.stringify(vetRaw) || '').substring(0, 4000);

const compRaw = $('DDG Competitor Search').first().json;
const compData = (compRaw.data || compRaw.body || JSON.stringify(compRaw) || '').substring(0, 4000);

return [{
  json: {
    ...prep,
    vetDiscussions: vetData,
    competitorData: compData
  }
}];

const aiRaw = $input.first().json.output || $input.first().json.text || '';
const prep = $('Merge All Intel').first().json;

let post = {};
try {
  const m = aiRaw.match(/\{[\s\S]*\}/);
  if (m) post = JSON.parse(m[0]);
} catch(e) {
  post = { post_text: aiRaw, hook: '', content_type: prep.contentType, product: prep.product };
}

return [{
  json: {
    postText: post.post_text || aiRaw,
    hook: post.hook || '',
    contentType: post.content_type || prep.contentType,
    product: post.product || prep.product,
    hashtags: post.hashtags || '',
    today: prep.today
  }
}];

const aiRaw = $input.first().json.output || $input.first().json.text || '';

function toStr(val) {
  if (val === null || val === undefined) return '';
  if (typeof val === 'string') return val;
  if (Array.isArray(val)) return val.map(v => typeof v === 'object' ? JSON.stringify(v) : String(v)).join('\n- ');
  if (typeof val === 'object') return Object.entries(val).map(([k,v]) => k + ': ' + (typeof v === 'object' ? JSON.stringify(v) : v)).join('\n');
  return String(val);
}

let intel = {};
try {
  const m = aiRaw.match(/\{[\s\S]*\}/);
  if (m) intel = JSON.parse(m[0]);
} catch(e) {
  intel = { competitor_updates: aiRaw, where_asteris_wins: 'Parse error', confidence: 'low' };
}

const bc = intel.battlecard || {};

return [{
  json: {
    competitorUpdates: toStr(intel.competitor_updates),
    customerSentiment: toStr(intel.customer_sentiment),
    whereAsterisWins: toStr(intel.where_asteris_wins),
    bcIdexx: toStr(bc.idexx),
    bcSoundAntech: toStr(bc.sound_antech),
    bcCovetrus: toStr(bc.covetrus),
    bcEvetpractice: toStr(bc.evetpractice),
    bcVetrocket: toStr(bc.vetrocket),
    actionItems: toStr(intel.action_items),
    confidence: toStr(intel.confidence) || 'low'
  }
}];

